import heapq
class Solution:
    def fillCups(self, amount: List[int]) -> int:
        heap = [-a for a in amount if a]
        heapq.heapify(heap)
        sec = 0
        while heap:
            sec += 1
            first = -heapq.heappop(heap)
            if heap:
                second = -heapq.heappop(heap)
                if second - 1 > 0: heapq.heappush(heap, -(second - 1))
            if first - 1 > 0: heapq.heappush(heap, -(first - 1))
        return sec

