class Solution {
public:
    int fillCups(vector<int>& amount) {
        priority_queue<int> pq;
        for (int a : amount) if (a) pq.push(a);
        int sec = 0;
        while (!pq.empty()) {
            sec++;
            int first = pq.top(); pq.pop();
            if (!pq.empty()) { int s = pq.top(); pq.pop(); if (--s > 0) pq.push(s); }
            if (--first > 0) pq.push(first);
        }
        return sec;
    }
};

