class Solution {
    public int fillCups(int[] amount) {
        PriorityQueue<Integer> pq = new PriorityQueue<>(Collections.reverseOrder());
        for (int a : amount) if (a > 0) pq.add(a);
        int sec = 0;
        while (!pq.isEmpty()) {
            sec++;
            int first = pq.poll() - 1;
            if (!pq.isEmpty()) { int s = pq.poll() - 1; if (s > 0) pq.add(s); }
            if (first > 0) pq.add(first);
        }
        return sec;
    }
}

