var fillCups = function(amount) {
    const h = [];
    for (const a of amount) if (a > 0) h.push(a);
    const pop = () => { let mx = 0, mi = -1; h.forEach((v, i) => { if (v > mx) { mx = v; mi = i; } }); if (mi >= 0) h.splice(mi, 1); return mx; };
    let sec = 0;
    while (h.length) {
        sec++;
        const f = pop() - 1;
        if (h.length) { const s = pop() - 1; if (s > 0) h.push(s); }
        if (f > 0) h.push(f);
    }
    return sec;
};
